import { z } from 'zod';

/** Recognize the provider's specific transient billing response, including old journals. */
export function isSkillInstallBillingBusy(message: string | undefined): boolean {
  return typeof message === 'string' && /unexpected status 503 Service Unavailable:\s*billing busy(?:\s*[,;]|\s*$)/i.test(message);
}

/** Client languages supported by installation analysis; optional on legacy requests/journals. */
export const SkillReviewLocale = z.enum(['en', 'zh', 'ja', 'de', 'es', 'fr', 'id', 'ko', 'pt', 'uk']);
export type SkillReviewLocale = z.infer<typeof SkillReviewLocale>;

// Strip only retired token caps so persisted installation snapshots remain readable.
export const SkillInstallModelConfig = z.preprocess(value => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const { candidateMaxTokens: _candidate, taskMaxTokens: _task, ...current } = value as Record<string, unknown>;
  return current;
}, z.object({
  model: z.string().trim().min(1).max(200),
  reasoningEffort: z.enum(['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra']),
  serviceTier: z.enum(['default', 'priority', 'flex']),
  requestTimeoutMs: z.number().int().min(5000).max(600_000),
  maxRepairRounds: z.number().int().min(0).max(4),
}).strict());
export type SkillInstallModelConfig = z.infer<typeof SkillInstallModelConfig>;

/** Serialized review snapshot: included text and every file's inventory, before protocol/schema overhead. */
export const SKILL_REVIEW_INPUT_MAX_BYTES = 2 * 1024 * 1024;
export const SKILL_REVIEW_BATCH_MAX_BYTES = 512 * 1024;
/** Reserve for native instructions, schema and protocol framing in each request. */
export const SKILL_REVIEW_REQUEST_OVERHEAD_BYTES = 64 * 1024;
/** Initial batches, with final synthesis included in the last batch. */
export const SKILL_REVIEW_MAX_REQUESTS = 4;
export const SKILL_REVIEW_MAX_BATCH_ATTEMPTS = 2;
/** Actual provider requests within one fixed batch/round, sharing the overall budgets. */
export const SKILL_REVIEW_MAX_MODEL_REQUESTS_PER_REVIEW = 3;
export const SKILL_REVIEW_TOTAL_MAX_REQUESTS = SKILL_REVIEW_MAX_REQUESTS * SKILL_REVIEW_MAX_BATCH_ATTEMPTS;
export const SKILL_REVIEW_TOTAL_INPUT_MAX_BYTES = SKILL_REVIEW_INPUT_MAX_BYTES * SKILL_REVIEW_MAX_BATCH_ATTEMPTS;

export const DEFAULT_SKILL_INSTALL_CONFIG: Readonly<SkillInstallModelConfig> = Object.freeze({
  model: 'gpt-6-luna', reasoningEffort: 'high', serviceTier: 'default',
  // Four different batches may each request one repair, across four repair cycles.
  requestTimeoutMs: 180_000, maxRepairRounds: 4,
});

export const SkillInstallStorageLimits = z.object({
  maxPendingTasks: z.number().int().min(1).max(1000),
  maxStagedBytes: z.number().int().min(1).max(Number.MAX_SAFE_INTEGER),
  pendingTtlMs: z.number().int().positive(),
  sourceTimeoutMs: z.number().int().min(1000).max(600_000),
}).strict();
export type SkillInstallStorageLimits = z.infer<typeof SkillInstallStorageLimits>;
export const DEFAULT_SKILL_INSTALL_STORAGE_LIMITS: Readonly<SkillInstallStorageLimits> = Object.freeze({
  maxPendingTasks: 20, maxStagedBytes: 1_073_741_824,
  pendingTtlMs: 7 * 24 * 3600_000, sourceTimeoutMs: 600_000,
});

/** Token usage is informational; request bytes/count and timeouts bound review work. */
export function resolveSkillInstallConfig(env: Readonly<Record<string, string | undefined>>,
  warn: (message: string) => void = () => {}, defaults = DEFAULT_SKILL_INSTALL_CONFIG): SkillInstallModelConfig {
  for (const key of ['SPARC3D_SKILL_INSTALL_MAX_TOKENS', 'SPARC3D_SKILL_INSTALL_TASK_MAX_TOKENS', 'SPARC3D_SKILL_INSTALL_CANDIDATE_MAX_TOKENS']) {
    if (env[key] !== undefined) warn(`${key} is retired and ignored; installation review is limited by request bytes and count.`);
  }
  const oldTimeout = env.SPARC3D_SKILL_INSTALL_TIMEOUT_MS;
  const integer = (key: string, fallback: number): number => {
    const raw = env[key];
    if (raw === undefined) return fallback;
    if (!/^\d+$/.test(raw.trim()) || !Number.isSafeInteger(Number(raw))) throw new Error(`Invalid installer configuration: ${key}`);
    return Number(raw);
  };
  const newTimeout = env.SPARC3D_SKILL_INSTALL_REQUEST_TIMEOUT_MS;
  if (oldTimeout !== undefined) warn(newTimeout !== undefined
    ? 'SPARC3D_SKILL_INSTALL_TIMEOUT_MS is deprecated and ignored in favor of REQUEST_TIMEOUT_MS.'
    : 'SPARC3D_SKILL_INSTALL_TIMEOUT_MS now limits each review request, excluding user waiting time.');
  const result = SkillInstallModelConfig.safeParse({ ...defaults,
    model: env.SPARC3D_SKILL_INSTALL_MODEL ?? defaults.model,
    requestTimeoutMs: integer(newTimeout !== undefined ? 'SPARC3D_SKILL_INSTALL_REQUEST_TIMEOUT_MS'
      : 'SPARC3D_SKILL_INSTALL_TIMEOUT_MS', defaults.requestTimeoutMs),
  });
  if (!result.success) throw new Error(`Invalid installer configuration: ${result.error.message}`);
  return result.data;
}
